"use client";

import { useState } from "react";
import { Box, Typography, Tabs, Tab, IconButton, Button, Chip } from "@mui/material";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import TokenIcon from "@mui/icons-material/Token";
import FileDownloadIcon from "@mui/icons-material/FileDownload";
import { CVPreview } from "./CVPreview";
import { TemplateSelector } from "./TemplateSelector";
import { AIAnalysisPanel } from "./AIAnalysisPanel";
import type { ParsedCV, TemplateType } from "@/types/cv";

interface CVWorkspaceProps {
  cv: ParsedCV;
  onBack: () => void;
  onUpdateCV: (cv: ParsedCV) => void;
}

type AssessmentTrack = "assessment" | "advisor" | "jd-match";

export function CVWorkspace({ cv, onBack, onUpdateCV }: CVWorkspaceProps) {
  const [template, setTemplate] = useState<TemplateType>("modern-dark");
  const [activeTrack, setActiveTrack] = useState<AssessmentTrack>("assessment");

  return (
    <Box sx={{ height: "100vh", display: "flex", flexDirection: "column", bgcolor: "background.default" }}>
      <Box 
        sx={{ 
          display: "flex", 
          alignItems: "center", 
          justifyContent: "space-between",
          gap: 2, 
          px: 3, 
          py: 1.5, 
          borderBottom: "1px solid",
          borderColor: "divider",
          bgcolor: "background.paper",
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <IconButton onClick={onBack} size="small" data-testid="button-back-dashboard">
            <ArrowBackIcon />
          </IconButton>
          <Box>
            <Typography variant="h6" sx={{ fontWeight: 600, lineHeight: 1.2 }}>
              {cv.name || "Untitled Resume"}
            </Typography>
            {cv.title && (
              <Typography variant="body2" color="text.secondary">
                {cv.title}
              </Typography>
            )}
          </Box>
        </Box>

        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          {cv.tokenUsage && (
            <Chip
              icon={<TokenIcon sx={{ fontSize: 16 }} />}
              label={`${cv.tokenUsage.totalTokens.toLocaleString()} tokens`}
              size="small"
              variant="outlined"
              data-testid="chip-token-usage"
            />
          )}
          <Button
            variant="outlined"
            size="small"
            startIcon={<FileDownloadIcon />}
            data-testid="button-export"
          >
            Export
          </Button>
        </Box>
      </Box>

      <Box sx={{ flex: 1, display: "flex", overflow: "hidden" }}>
        <Box 
          sx={{ 
            width: "55%", 
            borderRight: "1px solid",
            borderColor: "divider",
            display: "flex",
            flexDirection: "column",
            bgcolor: "background.paper",
          }}
        >
          <Box 
            sx={{ 
              display: "flex", 
              alignItems: "center", 
              justifyContent: "space-between",
              gap: 2,
              px: 3, 
              py: 1.5,
              borderBottom: "1px solid",
              borderColor: "divider",
            }}
          >
            <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>
              CV Preview
            </Typography>
            <TemplateSelector template={template} onTemplateChange={setTemplate} />
          </Box>
          
          <Box sx={{ flex: 1, overflow: "auto", p: 3 }}>
            <CVPreview cv={cv} template={template} onUpdateCV={onUpdateCV} />
          </Box>
        </Box>

        <Box 
          sx={{ 
            width: "45%", 
            display: "flex",
            flexDirection: "column",
            bgcolor: "background.default",
          }}
        >
          <Box 
            sx={{ 
              px: 2, 
              borderBottom: "1px solid",
              borderColor: "divider",
              bgcolor: "background.paper",
            }}
          >
            <Tabs 
              value={activeTrack} 
              onChange={(_, v) => setActiveTrack(v)}
              sx={{
                "& .MuiTab-root": {
                  textTransform: "none",
                  fontWeight: 500,
                  minHeight: 48,
                }
              }}
            >
              <Tab 
                value="assessment" 
                label="CV Assessment" 
                data-testid="tab-cv-assessment"
              />
              <Tab 
                value="advisor" 
                label="AI Advisor" 
                data-testid="tab-ai-advisor"
              />
              <Tab 
                value="jd-match" 
                label="JD Match" 
                data-testid="tab-jd-match"
              />
            </Tabs>
          </Box>

          <Box sx={{ flex: 1, overflow: "auto" }}>
            <AIAnalysisPanel cv={cv} activeTrack={activeTrack} />
          </Box>
        </Box>
      </Box>
    </Box>
  );
}
